mapper.update:
update product
set stock = stock - #{qty}, update_time = now()
where id = #{id} and stock >= #{qty}

update product
set stock = stock + #{qty}, update_time = now()
where id = #{id}

mapper.select:
SELECT p.id, p.name, p.price_in_cents, p.stock, p.image_url, p.category, p.is_flash_sale, p.flash_sale_at, p.description, p.create_time, p.update_time, COALESCE(s.sold, 0) AS sold, COALESCE(r.avg_rating, 0) AS avg_rating
AND p.category = #{q.category}
AND p.name LIKE CONCAT('%', #{kw}, '%')
ORDER BY
p.price_in_cents sold avg_rating p.create_time
${q.sortOrderSql}
